te-columns:9rem minmax(0,1fr);gap:1rem;padding-block:.8rem;border-top:1px solid var(--color-border)}.prototype-copy li span{color:var(--color-text-muted)}.source-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--space-l);margin-top:var(--space-2xl)}.source-grid article{min-width:0;padding:var(--space-l);border:1px solid var(--color-border);border-radius:var(--radius-lg);background:var(--color-surface)}.source-grid h3{margin:.45rem 0;font:500 var(--step-2)/1.15 var(--font-serif)}.source-grid article>p:not(.priority){color:var(--color-text-muted);font-size:var(--step--1);line-height:1.55}.source-grid a,.source-grid article>span{font:500 var(--step--1)/1.4 var(--font-mono);color:var(--color-accent);overflow-wrap:anywhere}.source-grid a{text-decoration:none}.contribute>div{display:grid;grid-template-columns:12rem minmax(0,1fr);gap:var(--space-xl);max-width:60rem}.contribute p{margin:0}.contribute ul{margin:0;padding-left:1.2rem;columns:2;line-height:1.8;color:var(--color-text-muted)}.closing{max-width:32ch;margin-top:var(--space-3xl)!important;font:500 var(--step-2)/1.3 var(--font-serif)}@media(max-width:760px){.principles,.refusals ul,.source-grid,.prototype{grid-template-columns:1fr}.record{grid-template-columns:repeat(2,minmax(0,1fr))}.prototype-copy li{grid-template-columns:1fr;gap:.25rem}.contribute>div{grid-template-columns:1fr;gap:var(--space-s)}.contribute ul{columns:1}}@media(max-width:440px){.record{grid-template-columns:1fr}h1{font-size:clamp(3.8rem,20vw,6rem)}}
